/// Utility classes and extensions for code generation
library;

import 'package:gql/ast.dart';

/// Constants for code generation
class CodeGenerationConstants {
  /// Warning header for generated files
  static const String generatedFileWarning =
      '''// THIS FILE IS GENERATED AUTOMATICALLY AND SHOULD NOT BE EDITED MANUALLY
// Any manual changes will be overwritten during code generation
// Generated by flutter_graphql_codegen''';

  /// Silences lints in generated files (placed after [generatedFileWarning]).
  static const String ignoreForFile = '// ignore_for_file: type=lint';
}

/// Extension methods for string manipulation
extension StringExtension on String {
  /// Capitalizes the first letter of the string
  String capitalize() {
    if (isEmpty) return this;
    return "${this[0].toUpperCase()}${substring(1)}";
  }

  /// Converts string to camelCase
  String toCamelCase() {
    if (length < 2) {
      return toLowerCase();
    }
    return "${this[0].toLowerCase()}${substring(1)}";
  }
}

/// Extension for TypeNode to check if it's non-null
extension TypeNodeExtensions on TypeNode {
  /// True if this node is marked non-null in the GraphQL AST
  bool get isNonNull {
    if (this is NamedTypeNode) {
      return (this as NamedTypeNode).isNonNull;
    }
    if (this is ListTypeNode) {
      return (this as ListTypeNode).isNonNull;
    }
    return false;
  }
}

/// Constants for GraphQL scalar types
class GraphQLConstants {
  static const Set<String> builtInScalars = {
    'Int',
    'Float',
    'String',
    'Boolean',
    'ID',
    'Short'
  };

  static const Map<String, String> scalarToDartType = {
    'Int': 'int',
    'Float': 'double',
    'String': 'String',
    'Boolean': 'bool',
    'ID': 'String',
    'Short': 'int',
    'DateTime': 'DateTime',
    'LocalDate': 'DateTime',
  };
}

/// Global state for tracking custom types and enums
class TypeRegistry {
  static final Set<String> _customScalars = <String>{};
  static final Set<String> _enumTypes = <String>{};
  static final Set<String> _objectTypes = <String>{};
  static final Set<String> _interfaceTypes = <String>{};
  static final Set<String> _unionTypes = <String>{};
  static final Set<String> _inputTypes = <String>{};

  /// Abstract type name (interface or union) -> sorted concrete object types.
  static final Map<String, List<String>> _possibleTypes = {};

  /// Object/interface type name -> abstract types it must implement in Dart
  /// (its GraphQL interfaces plus the unions it belongs to).
  static final Map<String, List<String>> _supertypes = {};

  static Set<String> get customScalars => _customScalars;
  static Set<String> get enumTypes => _enumTypes;
  static Set<String> get objectTypes => _objectTypes;
  static Set<String> get interfaceTypes => _interfaceTypes;
  static Set<String> get unionTypes => _unionTypes;
  static Set<String> get inputTypes => _inputTypes;

  static void clear() {
    _customScalars.clear();
    _enumTypes.clear();
    _objectTypes.clear();
    _interfaceTypes.clear();
    _unionTypes.clear();
    _inputTypes.clear();
    _possibleTypes.clear();
    _supertypes.clear();
  }

  static void addCustomScalar(String scalar) {
    _customScalars.add(scalar);
  }

  static void addEnumType(String enumType) {
    _enumTypes.add(enumType);
  }

  static void addObjectType(String typeName) {
    _objectTypes.add(typeName);
  }

  static void addInterfaceType(String typeName) {
    _interfaceTypes.add(typeName);
  }

  static void addUnionType(String typeName) {
    _unionTypes.add(typeName);
  }

  static void addInputType(String typeName) {
    _inputTypes.add(typeName);
  }

  /// Records that [concreteType] can appear where [abstractType] is expected.
  static void addPossibleType(String abstractType, String concreteType) {
    final list = _possibleTypes.putIfAbsent(abstractType, () => []);
    if (!list.contains(concreteType)) {
      list
        ..add(concreteType)
        ..sort();
    }
  }

  /// Records that [typeName] implements [abstractType] in Dart.
  static void addSupertype(String typeName, String abstractType) {
    final list = _supertypes.putIfAbsent(typeName, () => []);
    if (!list.contains(abstractType)) {
      list
        ..add(abstractType)
        ..sort();
    }
  }

  static List<String> possibleTypes(String abstractType) =>
      _possibleTypes[abstractType] ?? const [];

  static List<String> supertypes(String typeName) =>
      _supertypes[typeName] ?? const [];

  static bool isEnum(String typeName) {
    return _enumTypes.contains(typeName);
  }

  static bool isCustomScalar(String typeName) {
    return _customScalars.contains(typeName);
  }

  /// True for interfaces and unions.
  static bool isAbstract(String typeName) =>
      _interfaceTypes.contains(typeName) || _unionTypes.contains(typeName);

  /// Scalars with a built-in Dart representation instead of a generated
  /// wrapper class.
  static const Set<String> builtInScalarTypes = {
    'Decimal', 'DateTime', 'Short', 'Byte', 'Long', 'LocalDate', //
  };

  /// True for custom scalars that get a generated wrapper class.
  static bool isWrappedScalar(String typeName) =>
      _customScalars.contains(typeName) &&
      !builtInScalarTypes.contains(typeName);

  /// True when the generator declares a Dart type for schema type [typeName]
  /// (object, input, interface, union, enum or wrapped custom scalar).
  static bool declaresType(String typeName) =>
      _objectTypes.contains(typeName) ||
      _inputTypes.contains(typeName) ||
      _enumTypes.contains(typeName) ||
      isAbstract(typeName) ||
      isWrappedScalar(typeName);
}
